using ScaleDesk.Domain.Common;

namespace ScaleDesk.Domain.Entities;

/// <summary>
/// A user-facing notification generated by the Kafka consumer from domain events (§22).
/// Tenant-scoped for strict isolation; addressed to a specific recipient. The API exposes
/// list + mark-read, and the SignalR hub pushes new ones in real time (Slice 4).
/// </summary>
public class Notification : BaseEntity, ITenantOwned
{
    public Guid TenantId { get; set; }

    /// <summary>The user who should see this notification in their bell / feed.</summary>
    public Guid RecipientUserId { get; set; }

    /// <summary>Event-derived classification: "ticket.assigned", "sla.breached", etc.</summary>
    public string Type { get; set; } = default!;

    public string Title { get; set; } = default!;

    public string? Body { get; set; }

    /// <summary>Optional deep-link context for the frontend.</summary>
    public Guid? RelatedTicketId { get; set; }

    public bool IsRead { get; set; }
}
